import{_ as e,o as a,c as i,ag as s}from"./chunks/framework.ePeAWSvT.js";const u=JSON.parse('{"title":"Quick Start","description":"","frontmatter":{},"headers":[],"relativePath":"guide/quick-start.md","filePath":"guide/quick-start.md","lastUpdated":1772297611000}'),r={name:"guide/quick-start.md"};function o(n,t,l,p,c,h){return a(),i("div",null,[...t[0]||(t[0]=[s(`<h1 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick Start&quot;">​</a></h1><p>Get NectoProxy up and running in under five minutes. This guide walks you through the essential steps to start capturing and inspecting HTTP/HTTPS traffic.</p><h2 id="step-1-install-nectoproxy" tabindex="-1">Step 1: Install NectoProxy <a class="header-anchor" href="#step-1-install-nectoproxy" aria-label="Permalink to &quot;Step 1: Install NectoProxy&quot;">​</a></h2><p>Install NectoProxy globally via npm:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nectoproxy</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Alternative: Use npx</p><p>If you prefer not to install globally, run NectoProxy directly:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nectoproxy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div></div><h2 id="step-2-start-the-proxy" tabindex="-1">Step 2: Start the Proxy <a class="header-anchor" href="#step-2-start-the-proxy" aria-label="Permalink to &quot;Step 2: Start the Proxy&quot;">​</a></h2><p>Launch NectoProxy from your terminal:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nectoproxy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><p>You should see output similar to:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  NectoProxy v0.1.0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  Proxy server running on http://127.0.0.1:8888</span></span>
<span class="line"><span>  Web UI available at  http://127.0.0.1:8889</span></span></code></pre></div><p>NectoProxy starts two services:</p><table tabindex="0"><thead><tr><th>Service</th><th>Default Address</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>Proxy Server</strong></td><td><code>127.0.0.1:8888</code></td><td>The HTTP/HTTPS proxy that intercepts traffic</td></tr><tr><td><strong>Web UI</strong></td><td><code>127.0.0.1:8889</code></td><td>The browser-based dashboard for viewing traffic</td></tr></tbody></table><p>The Web UI opens automatically in your default browser.</p><h2 id="step-3-configure-your-browser-proxy" tabindex="-1">Step 3: Configure Your Browser Proxy <a class="header-anchor" href="#step-3-configure-your-browser-proxy" aria-label="Permalink to &quot;Step 3: Configure Your Browser Proxy&quot;">​</a></h2><p>Point your browser (or system) HTTP proxy to NectoProxy so that traffic flows through it.</p><h3 id="browser-configuration" tabindex="-1">Browser Configuration <a class="header-anchor" href="#browser-configuration" aria-label="Permalink to &quot;Browser Configuration&quot;">​</a></h3><p><strong>Option A: System-wide proxy (recommended for quick testing)</strong></p><p>Configure your operating system&#39;s network proxy settings to use <code>127.0.0.1</code> on port <code>8888</code> for both HTTP and HTTPS traffic.</p><ul><li><strong>macOS</strong>: System Settings &gt; Network &gt; Wi-Fi &gt; Details &gt; Proxies &gt; Enable Web Proxy (HTTP) and Secure Web Proxy (HTTPS), set server to <code>127.0.0.1</code> and port to <code>8888</code>.</li><li><strong>Windows</strong>: Settings &gt; Network &amp; Internet &gt; Proxy &gt; Manual proxy setup &gt; Use a proxy server &gt; Address <code>127.0.0.1</code>, Port <code>8888</code>.</li><li><strong>Linux</strong>: Network Settings &gt; Network Proxy &gt; Manual &gt; HTTP/HTTPS Proxy <code>127.0.0.1:8888</code>.</li></ul><p><strong>Option B: Browser-only proxy extension</strong></p><p>Use a browser extension like <a href="https://getfoxyproxy.org/" target="_blank" rel="noreferrer">FoxyProxy</a> or <a href="https://github.com/nicehash/nicehash-SwitchyOmega" target="_blank" rel="noreferrer">Proxy SwitchyOmega</a> to route only browser traffic through NectoProxy without affecting other system traffic.</p><p>Set the proxy to:</p><ul><li><strong>Protocol</strong>: HTTP</li><li><strong>Server</strong>: <code>127.0.0.1</code></li><li><strong>Port</strong>: <code>8888</code></li></ul><div class="warning custom-block"><p class="custom-block-title">HTTPS Proxy Setting</p><p>Make sure you configure <strong>both</strong> HTTP and HTTPS proxy settings to point to <code>127.0.0.1:8888</code>. NectoProxy handles HTTPS interception via the HTTP CONNECT method, so the HTTPS proxy address is the same as the HTTP proxy address.</p></div><h2 id="step-4-install-the-ca-certificate" tabindex="-1">Step 4: Install the CA Certificate <a class="header-anchor" href="#step-4-install-the-ca-certificate" aria-label="Permalink to &quot;Step 4: Install the CA Certificate&quot;">​</a></h2><p>To inspect HTTPS traffic, NectoProxy needs its root CA certificate trusted by your system or browser. Without it, you will see SSL certificate warnings for every HTTPS site.</p><p>Run the certificate installation helper:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nectoproxy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cert</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --install</span></span></code></pre></div><p>This prints platform-specific instructions for installing the CA certificate. Follow the instructions for your operating system:</p><ul><li><a href="/certificate/macos.html">macOS Certificate Setup</a></li><li><a href="/certificate/windows.html">Windows Certificate Setup</a></li><li><a href="/certificate/linux.html">Linux Certificate Setup</a></li><li><a href="/certificate/firefox.html">Firefox Certificate Setup</a></li><li><a href="/certificate/mobile.html">Mobile Devices</a></li></ul><div class="tip custom-block"><p class="custom-block-title">Quick macOS Install</p><p>On macOS, you can install the certificate in one command:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> security</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add-trusted-cert</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> trustRoot</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -k</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /Library/Keychains/System.keychain</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  ~/.nectoproxy/certs/ca.pem</span></span></code></pre></div></div><h2 id="step-5-browse-and-inspect-traffic" tabindex="-1">Step 5: Browse and Inspect Traffic <a class="header-anchor" href="#step-5-browse-and-inspect-traffic" aria-label="Permalink to &quot;Step 5: Browse and Inspect Traffic&quot;">​</a></h2><p>With the proxy configured and the CA certificate installed, start browsing. Every HTTP and HTTPS request will appear in the NectoProxy Web UI in real time.</p><p>Open the Web UI at <a href="http://127.0.0.1:8889" target="_blank" rel="noreferrer">http://127.0.0.1:8889</a> and you will see:</p><ol><li><strong>Traffic List</strong> -- A live-updating list of all intercepted requests showing method, URL, status code, size, and timing.</li><li><strong>Request Details</strong> -- Click any request to inspect its full headers, body (with syntax highlighting), timing breakdown, and TLS information.</li><li><strong>Response Details</strong> -- View the complete server response including headers and decoded body content.</li></ol><details class="details custom-block"><summary>What If I Don&#39;t See Any Traffic?</summary><p>If requests are not appearing in the Web UI:</p><ol><li><strong>Verify proxy settings</strong> -- Confirm your browser is actually routing through <code>127.0.0.1:8888</code>. Visit <code>http://httpbin.org/ip</code> and check if requests appear.</li><li><strong>Check NectoProxy is running</strong> -- Ensure the terminal window running <code>nectoproxy start</code> is still active.</li><li><strong>Firewall issues</strong> -- Some firewalls or security software may block local proxy connections. Temporarily disable them to test.</li><li><strong>HTTPS without certificate</strong> -- If HTTP requests appear but HTTPS do not, you need to install the CA certificate (Step 4).</li></ol></details><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><p>Now that you have NectoProxy running and capturing traffic, explore these powerful features:</p><h3 id="traffic-rules" tabindex="-1">Traffic Rules <a class="header-anchor" href="#traffic-rules" aria-label="Permalink to &quot;Traffic Rules&quot;">​</a></h3><p>Create rules to automatically modify, mock, block, delay, or redirect matching requests. Rules let you test your application against different scenarios without changing any code.</p><h3 id="breakpoints" tabindex="-1">Breakpoints <a class="header-anchor" href="#breakpoints" aria-label="Permalink to &quot;Breakpoints&quot;">​</a></h3><p>Set breakpoints on specific requests or responses to pause them mid-flight. You can manually inspect and modify headers, bodies, and status codes before forwarding -- perfect for debugging tricky API interactions.</p><h3 id="network-conditioning" tabindex="-1">Network Conditioning <a class="header-anchor" href="#network-conditioning" aria-label="Permalink to &quot;Network Conditioning&quot;">​</a></h3><p>Simulate slow or unreliable network conditions to test how your application handles real-world scenarios. Apply bandwidth limits, latency, and packet loss using built-in profiles like 3G, slow Wi-Fi, or create custom profiles.</p><h3 id="code-generation" tabindex="-1">Code Generation <a class="header-anchor" href="#code-generation" aria-label="Permalink to &quot;Code Generation&quot;">​</a></h3><p>Capture a request and instantly generate equivalent code in cURL, Python, Node.js, Go, PHP, Rust, and more. Useful for reproducing issues or building API client code.</p><h3 id="har-export" tabindex="-1">HAR Export <a class="header-anchor" href="#har-export" aria-label="Permalink to &quot;HAR Export&quot;">​</a></h3><p>Export your captured traffic as a HAR (HTTP Archive) file to share with colleagues, attach to bug reports, or import into other analysis tools.</p><h3 id="request-comparison" tabindex="-1">Request Comparison <a class="header-anchor" href="#request-comparison" aria-label="Permalink to &quot;Request Comparison&quot;">​</a></h3><p>Select two captured requests and diff them side by side to identify differences in headers, query parameters, or request bodies.</p>`,51)])])}const g=e(r,[["render",o]]);export{u as __pageData,g as default};
